function isPlaceableItem(id){const def=itemDef(id);return !!(def.placeable||def.type==='block'||def.buildShape||id==='wall'||id==='stonewall');}
function buildPieceGeometry(id){
 if(id==='floor'||id==='path'||id==='stonepath')return new THREE.BoxGeometry(1,.14,1);
 if(id==='beam')return new THREE.BoxGeometry(.18,.18,1);
 if(id==='stairs'){const shape=new THREE.Shape();shape.moveTo(-.5,-.5);shape.lineTo(.5,-.5);shape.lineTo(.5,.5);shape.lineTo(0,.5);shape.lineTo(0,0);shape.lineTo(-.5,0);shape.closePath();const g=new THREE.ExtrudeGeometry(shape,{depth:1,bevelEnabled:false});g.translate(0,0,-.5);return g;}
 if(id==='fence')return new THREE.BoxGeometry(1,.16,.78);
 if(id==='door')return new THREE.BoxGeometry(.82,1,.13);
 if(id==='glass')return new THREE.BoxGeometry(.92,.92,.075);
 if(id==='roof')return new THREE.BoxGeometry(1,.16,1);
 if(id==='lantern')return new THREE.OctahedronGeometry(.27,0);
 if(id==='campfire')return new THREE.CylinderGeometry(.28,.38,.2,7);
 return cubeGeo;
}
function buildPieceDimensions(id){if(id==='floor'||id==='path'||id==='stonepath')return [.98,.16,.98];return [1,1,1];}
function createBuildPiece(id,x,y,z,color,parent=worldGroup,key=null,rotation=0){
 const def=itemDef(id),geometry=buildPieceGeometry(id),isGlass=id==='glass',isLantern=id==='lantern';
 let mat;if(isGlass)mat=new THREE.MeshStandardMaterial({color:color||0x9dcbd0,roughness:.18,metalness:.08,transparent:true,opacity:.52});else if(isLantern)mat=new THREE.MeshStandardMaterial({color:color||0xd4b477,roughness:.45,emissive:color||0xd4b477,emissiveIntensity:.48});else mat=material(color||def.color||(id==='stonewall'?0x858e8b:0x805c3c),.82,id==='stonewall'?.04:0);
 const mesh=new THREE.Mesh(geometry,mat);mesh.position.set(x,y,z);mesh.rotation.y=(rotation||0)*Math.PI/2;if(id==='lantern')mesh.position.y+=.28;if(id==='campfire')mesh.position.y-=.35;mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData={drop:id,hardness:1,block:true,placeable:true,buildShape:def.buildShape||id,chunkKey:key,gridX:x,gridY:y,gridZ:z,buildRotation:rotation};parent.add(mesh);blocks.push(mesh);worldObjects.push(mesh);return mesh;
}
function updateBuildPreview(){
 const id=state.hotbar[state.selected],active=started&&!paused&&state.buildMode&&isPlaceableItem(id);
 if(!active){buildPreview.visible=false;buildPreviewTarget=null;buildPreviewValid=false;return;}
 raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(blocks,true)[0];
 if(!hit){buildPreview.visible=false;buildPreviewTarget=null;buildPreviewValid=false;return;}
 const point=hit.point.clone().add(hit.face.normal.clone().multiplyScalar(.52));
 const x=Math.round(point.x),y=Math.round(point.y),z=Math.round(point.z);
 const occupied=blocks.some(b=>!b.isInstancedMesh&&b.userData.block&&Math.abs((b.userData.gridX??b.position.x)-x)<.2&&Math.abs((b.userData.gridY??b.position.y)-y)<.2&&Math.abs((b.userData.gridZ??b.position.z)-z)<.2);
 const playerSpace=Math.hypot(player.x-x,player.z-z)<.68&&Math.abs(player.y-y)<1.2;
 buildPreviewTarget={x,y,z};buildPreviewValid=!occupied&&!playerSpace;
 const def=itemDef(id),dims=buildPieceDimensions(id);buildPreview.scale.set(...dims);buildPreview.position.set(x,y+(id==='floor'||id==='path'||id==='stonepath'?-0.42:0),z);buildPreview.rotation.y=(state.buildRotation||0)*Math.PI/2;buildPreviewMaterialColor(buildPreviewValid,def.color||0x9fc28a);buildPreview.visible=true;
}
function buildPreviewMaterialColor(valid,color){buildGhostMaterial.color.setHex(valid?(color||0x9fc28a):0xb86d5e);buildGhostMaterial.opacity=valid?.68:.28;}
function toggleBuildMode(force){state.buildMode=typeof force==='boolean'?force:!state.buildMode;if(state.buildMode&&!isPlaceableItem(state.hotbar[state.selected])){const slot=state.hotbar.findIndex(id=>isPlaceableItem(id)&&(state.mode==='creative'||(state.inventory[id]||0)>0));if(slot>=0){state.selected=slot;renderHotbar();}}$('#build-mode-chip').classList.toggle('hidden',!state.buildMode);toast(state.buildMode?'Build mode · grid snapping and Z rotation enabled.':'Build mode closed.');if(!state.buildMode){buildPreview.visible=false;buildPreviewTarget=null;}}
function openBuildPalette(){
 const pieces=Object.keys(BASE_ITEMS).filter(id=>isPlaceableItem(id));
 const community=Object.keys(customItems()).filter(id=>isPlaceableItem(id));
 const ids=[...new Set([...pieces,...community])];
 openModal('<span class="eyebrow">SETTLEMENT WORKSHOP · BUILD CATALOGUE</span><h2>Choose your materials.</h2><p>Select a piece to assign it to your active hotbar slot. Press G to toggle the build grid and Z to rotate the placement preview.</p><div class="build-palette-grid">'+ids.map(id=>{const d=itemDef(id),owned=state.inventory[id]||0;return '<button class="build-piece-card" data-build-item="'+escapeHtml(id)+'"><span>'+escapeHtml(d.icon)+'</span><b>'+escapeHtml(d.name)+'</b><small>'+(state.mode==='creative'?'UNLIMITED':owned+' IN PACK')+'</small></button>';}).join('')+'</div><div class="modal-actions"><button class="button-secondary" id="build-palette-close">CLOSE</button><button class="button-primary" id="build-palette-craft">OPEN WORKBENCH</button></div>');
 $('.build-piece-card').forEach(b=>b.onclick=()=>{state.hotbar[state.selected]=b.dataset.buildItem;renderHotbar();toggleBuildMode(true);closeModal();});
 $('#build-palette-close').onclick=closeModal;$('#build-palette-craft').onclick=openCrafting;
}
