function customItems(){const all={};for(const p of enabledPacks()){for(const it of (p.content?.items||[]))all[it.id]={...it,type:it.type||'material'};for(const w of (p.content?.weapons||[]))all[w.id]={...w,type:'weapon',damage:w.damage||14,icon:w.icon||'⚔️'};for(const v of (p.content?.vehicles||[]))all[v.id]={...v,type:'vehicle',vehicle:true,icon:v.icon||'🛞'};}return all;}
