function addBuilding(x,z,kind='ruin',parent=worldGroup,chunkKeyValue=null){const group=new THREE.Group(),d=getRealmDef(state.realm),stone=material(d.rock,.93);for(let i=0;i<5;i++){const h=new THREE.Mesh(cubeGeo,stone);h.position.set(i-2,1,0);h.scale.set(1,2.5,1);h.castShadow=true;group.add(h);}const beam=new THREE.Mesh(cubeGeo,material(d.accent,.5,.1,.35));beam.position.set(0,3,.0);beam.scale.set(5,.25,.4);group.add(beam);group.position.set(x,terrainHeight(x,z),z);group.userData={kind,chunkKey:chunkKeyValue,ruinId:'ruin-'+state.realm+'-'+state.worldSeed+'-'+chunkKeyValue};parent.add(group);interactables.push(group);return group;}
function makeBeacon(){const g=new THREE.Group();const d=getRealmDef(state.realm);const base=new THREE.Mesh(new THREE.CylinderGeometry(2.2,2.5,.8,8),material(d.rock));base.position.y=.4;base.castShadow=true;g.add(base);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.35,.12,8,24),material(d.accent,.25,.2,.5));ring.position.y=2;ring.rotation.x=Math.PI/2;g.add(ring);const core=new THREE.Mesh(new THREE.OctahedronGeometry(.75),material(d.accent,.18,.25,.9));core.position.y=2;g.add(core);g.position.set(-7,terrainHeight(-7,1),1);g.userData={kind:'beacon'};worldGroup.add(g);interactables.push(g);return g;}
function makePortal(){const g=new THREE.Group();const d=getRealmDef(state.realm);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.8,.18,8,32),material(d.accent,.25,.2,.6));ring.position.y=2;g.add(ring);const portal=new THREE.Mesh(new THREE.CircleGeometry(1.58,32),new THREE.MeshBasicMaterial({color:d.accent,transparent:true,opacity:.18,side:THREE.DoubleSide}));portal.position.y=2;g.add(portal);g.position.set(7,terrainHeight(7,-2),-2);g.userData={kind:'portal'};worldGroup.add(g);interactables.push(g);for(let i=0;i<4;i++){const p=new THREE.Mesh(new THREE.OctahedronGeometry(.25),material(d.accent,.2,.2,.8));const a=i*Math.PI/2;p.position.set(2.2*Math.cos(a),2+2.2*Math.sin(a),0);g.add(p)}return g;}
function makeDungeon(){const g=new THREE.Group();const d=getRealmDef(state.realm),stone=material(d.rock,.92),rune=material(d.accent,.3,.15,.6);for(let i=0;i<6;i++){const pillar=new THREE.Mesh(cubeGeo,stone);pillar.position.set((i%3-1)*2.2,1.1,Math.floor(i/3)*1.8-1);pillar.scale.set(.8,3.1,.8);pillar.castShadow=true;g.add(pillar);}const cap=new THREE.Mesh(cubeGeo,rune);cap.position.set(0,3,0);cap.scale.set(7,.35,1.2);g.add(cap);for(let i=0;i<5;i++){const step=new THREE.Mesh(cubeGeo,stone);step.position.set(0,.2+i*.13,2.4+i*.55);step.scale.set(4-i*.35,.35,.65);g.add(step);}const seal=new THREE.Mesh(new THREE.TorusGeometry(1.1,.09,8,24),rune);seal.position.set(0,1.8,-.2);seal.rotation.x=Math.PI/2;g.add(seal);g.position.set(0,terrainHeight(0,-12),-12);g.userData={kind:'dungeon'};worldGroup.add(g);interactables.push(g);return g;}
function addCreature(def,x,z,hostile=false,boss=false,stableId=null,chunkKey=null,parent=worldGroup){const group=new THREE.Group();const color=def.color||0x92a879;const body=new THREE.Mesh(new THREE.DodecahedronGeometry(boss?1.3:.55,0),material(color,.7,.05,boss?.15:0));body.position.y=boss?1.5:.7;body.castShadow=true;group.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(boss?.55:.32,10,8),material(def.face||0xd8c79f));head.position.set(0,boss?2.35:1.15,.48);head.castShadow=true;group.add(head);for(let i=0;i<4;i++){const leg=new THREE.Mesh(cubeGeo,material(def.leg||color));leg.position.set(i<2?-.32:.32,.28,i%2?-.28:.28);leg.scale.set(.15,.6,.15);group.add(leg)}group.position.set(x,terrainHeight(x,z),z);const creatureId=stableId||def.id||uid();group.userData={kind:'creature',id:creatureId,name:def.name||'Wildling',hp:def.hp||25,maxHp:def.hp||25,hostile,boss,tamed:state.tamed.includes(creatureId),follow:state.tamed.includes(creatureId),damage:def.damage||5,speed:def.speed||1.5,def,attack:0,chunkKey,aiState:hostile?'stalk':'wander',nextThink:0,patrolAngle:hash(x,z,19)*Math.PI*2};group.userData.chunkKey=chunkKey;parent.add(group);if(hostile||boss)enemies.push(group);else creatures.push(group);return group;}
let boss=null,beacon=null,portal=null,dungeon=null,vehicleRig=null;
function chunkKey(cx,cz){return cx+','+cz;}
function chunkCoord(v){return Math.floor(v/CHUNK_SIZE);}
function editKey(x,y,z){return Math.round(x)+','+Math.round(y)+','+Math.round(z);}
function removedEditSet(realm){return new Set((state.worldEdits?.[realm]||[]).filter(e=>e.type==='remove').map(e=>editKey(e.x,e.y,e.z)));}
function makeTerrainBatch(parent,entries,color,drop,key){
 if(!entries.length)return null;
 const mesh=new THREE.InstancedMesh(cubeGeo,material(color,.96),entries.length);
 const matrix=new THREE.Matrix4();
 entries.forEach((p,i)=>{matrix.makeTranslation(p.x,p.y,p.z);mesh.setMatrixAt(i,matrix);});
 mesh.instanceMatrix.needsUpdate=true;mesh.castShadow=false;mesh.receiveShadow=true;mesh.userData={terrainChunk:true,positions:entries,drop,chunkKey:key,hardness:1};
 mesh.computeBoundingSphere();parent.add(mesh);blocks.push(mesh);worldObjects.push(mesh);return mesh;
}
function nativeCreaturesForRealm(name){
 if(name==='Verdantia')return [{name:'Mossback',color:0x77916a,face:0xb9c59c,hp:40,damage:6,speed:2.2,mount:true},{name:'Glimmerfox',color:0xc57a5e,face:0xe9c7a5,hp:20,damage:4,speed:3}];
 if(name==='Cinderdeep')return [{name:'Cindermite',color:0xc45d3f,face:0xffc06a,hp:24,damage:7,speed:2.2},{name:'Ashhorn',color:0x534847,face:0xff9f64,hp:50,damage:12,speed:1.8,mount:true}];
 if(name==='Skyreach')return [{name:'Cloudwing',color:0x9dc4ca,face:0xe5f1e9,hp:28,damage:5,speed:3,mount:true},{name:'Aeriesprite',color:0xa5bce1,face:0xf2e6ff,hp:18,damage:4,speed:2.8}];
 return [{name:'Gloamstag',color:0x566276,face:0xc2b4dd,hp:35,damage:8,speed:2,mount:true},{name:'Lumenling',color:0x97a6b6,face:0xe1d8ff,hp:18,damage:4,speed:2.6}];
}
function applyChunkEdits(key,cx,cz,parent){
 const edits=state.worldEdits?.[state.realm]||[];
 for(const edit of edits){if(edit.type!=='place')continue;const ex=chunkCoord(edit.x),ez=chunkCoord(edit.z);if(ex===cx&&ez===cz)createCube(edit.x,edit.y,edit.z,edit.color,edit.drop||'stone',{hardness:1,parent,chunkKey:key});}
}
function generateChunk(cx,cz){
 const key=chunkKey(cx,cz);if(loadedChunks.has(key))return;
 const parent=new THREE.Group();parent.userData.chunkKey=key;worldGroup.add(parent);
 const def=getRealmDef(state.realm),removed=removedEditSet(state.realm),surface=[],soil=[],deep=[];
 const startX=cx*CHUNK_SIZE,startZ=cz*CHUNK_SIZE;
 for(let lx=0;lx<CHUNK_SIZE;lx++)for(let lz=0;lz<CHUNK_SIZE;lz++){
  const x=startX+lx,z=startZ+lz,h=terrainHeight(x,z);
  if(!removed.has(editKey(x,h,z)))surface.push({x,y:h,z});
  for(let y=0;y<h;y++)if(!removed.has(editKey(x,y,z)))soil.push({x,y,z});
  for(let y=-2;y<0;y++)if(!removed.has(editKey(x,y,z)))deep.push({x,y,z});
 }
 const surfaceDrop=state.realm==='Verdantia'?'fibre':state.realm==='Cinderdeep'?'ember':state.realm==='Skyreach'?'cloudglass':'lumen';
 makeTerrainBatch(parent,surface,def.top,surfaceDrop,key);
 makeTerrainBatch(parent,soil,def.soil,'stone',key);
 makeTerrainBatch(parent,deep,def.rock,'stone',key);
 // Features are derived from world coordinates and the expedition seed, so reloading a chunk recreates it consistently.
 for(let i=0;i<3;i++){
  const x=startX+2+Math.floor(hash(cx*17+i,cz*29+i,state.worldSeed+31)*12);
  const z=startZ+2+Math.floor(hash(cx*23+i,cz*11+i,state.worldSeed+47)*12);
  if(Math.abs(x)<7&&Math.abs(z)<7)continue;
  if(!state.depletedNodes?.includes('tree-'+state.realm+'-'+key+'-'+Math.round(x)+'-'+Math.round(z))&&(state.realm!=='Cinderdeep'||hash(cx+i,cz-i,state.worldSeed+62)>.32))addPlant(x,z,{tall:2.1+hash(x,z,state.worldSeed+1)*1.8,leaf:state.realm==='Umbral Wilds'?0x546d7b:state.realm==='Cinderdeep'?0x634333:state.realm==='Skyreach'?0x789e9b:0x416b45},parent,key);
 }
 for(let i=0;i<3;i++){
  const x=startX+1+Math.floor(hash(cx*7+i,cz*13+i,state.worldSeed+72)*14);
  const z=startZ+1+Math.floor(hash(cx*19+i,cz*5+i,state.worldSeed+88)*14);
  if(Math.abs(x)<5&&Math.abs(z)<5)continue;
  const rare=hash(x,z,state.worldSeed+93)>.83;
  const drop=rare?(state.realm==='Verdantia'?'ore':state.realm==='Cinderdeep'?'ember':state.realm==='Skyreach'?'cloudglass':'lumen'):'stone';
  if(!state.depletedNodes?.includes('rock-'+state.realm+'-'+key+'-'+Math.round(x)+'-'+Math.round(z)))addRock(x,z,rare?def.accent:def.rock,drop,rare?.85:1,parent,key);
 }
 if(state.realm==='Skyreach'&&hash(cx,cz,state.worldSeed+104)>.35){
  const island=new THREE.Mesh(new THREE.DodecahedronGeometry(3.1,0),material(0x8caaa6));
  island.position.set(startX+8,10+hash(cx,cz,state.worldSeed+105)*6,startZ+8);island.scale.y=.42;island.castShadow=true;parent.add(island);
 }
 if(hash(cx,cz,state.worldSeed+111)>.91)addBuilding(startX+8,startZ+8,'ruin',parent,key);
 const wildlife=nativeCreaturesForRealm(state.realm),community=contentOf('creatures');
 if(hash(cx,cz,state.worldSeed+121)>.48){
  const x=startX+4+hash(cx,cz,state.worldSeed+122)*8,z=startZ+4+hash(cx,cz,state.worldSeed+123)*8;
  const def=community.length&&hash(cx,cz,state.worldSeed+124)>.7?community[Math.floor(hash(cx,cz,state.worldSeed+125)*community.length)]:wildlife[Math.floor(hash(cx,cz,state.worldSeed+126)*wildlife.length)];
  addCreature(def,x,z,false,false,'wild-'+getRealmDef(state.realm).id+'-'+key+'-'+def.name, key,parent);
 }
 if(hash(cx,cz,state.worldSeed+131)>.78){
  const x=startX+4+hash(cx,cz,state.worldSeed+132)*8,z=startZ+4+hash(cx,cz,state.worldSeed+133)*8;
  const hostileName=['Brambleling','Ash Wisp','Rift Stalker','Hollow Knight'][Object.keys(REALMS).indexOf(state.realm)]||'Rift Stalker';
  addCreature({name:hostileName,color:state.realm==='Cinderdeep'?0x8f402c:state.realm==='Umbral Wilds'?0x48465b:0x5b5044,face:def.accent,hp:28,damage:6,speed:1.5},x,z,true,false,'hostile-'+getRealmDef(state.realm).id+'-'+key,key,parent);
 }
 applyChunkEdits(key,cx,cz,parent);
 loadedChunks.set(key,{group:parent,cx,cz});
}
function updateChunks(x,z,force=false){
 const ccx=chunkCoord(x),ccz=chunkCoord(z),center=chunkKey(ccx,ccz);
 if(!force&&center===lastChunkCenter)return;
 lastChunkCenter=center;
 for(let cx=ccx-CHUNK_RADIUS;cx<=ccx+CHUNK_RADIUS;cx++)for(let cz=ccz-CHUNK_RADIUS;cz<=ccz+CHUNK_RADIUS;cz++)generateChunk(cx,cz);
 for(const [key,chunk] of [...loadedChunks.entries()]){
  if(Math.abs(chunk.cx-ccx)<=CHUNK_RADIUS&&Math.abs(chunk.cz-ccz)<=CHUNK_RADIUS)continue;
  worldGroup.remove(chunk.group);loadedChunks.delete(key);
  blocks=blocks.filter(o=>o.userData.chunkKey!==key);worldObjects=worldObjects.filter(o=>o.userData.chunkKey!==key);
  enemies=enemies.filter(o=>o.userData.chunkKey!==key);creatures=creatures.filter(o=>o.userData.chunkKey!==key);
  interactables=interactables.filter(o=>o.userData?.chunkKey!==key);trees=trees.filter(o=>o.userData.chunkKey!==key);
 }
}
function generateRealm(name){
 state.realm=name;state.activeDungeon={active:false,realm:name};const d=getRealmDef(name);clearWorld();
 scene.background=new THREE.Color(d.sky);scene.fog.color.setHex(d.fog);scene.fog.density=name==='Umbral Wilds'?.022:.012;
 sun.color.setHex(name==='Cinderdeep'?0xff9c68:name==='Umbral Wilds'?0xc3b2ef:0xffe7bd);sun.intensity=name==='Cinderdeep'?1.45:1.95;
 player.x=0;player.z=8;player.y=terrainHeight(0,8)+2;verticalVelocity=0;
 updateChunks(player.x,player.z,true);
 beacon=makeBeacon();portal=makePortal();dungeon=makeDungeon();
 if(name==='Verdantia')makeNpc('Mira, the Rootkeeper',-11,-7,'The old paths are growing over. I remember the Heart Loom before the Sundering. Find the first Anchor Shard and I may remember more.',[{name:'Lost Seed Pouch',description:'Search a forgotten ruin for a seed pouch.'}]);
 else makeNpc(name==='Cinderdeep'?'Korr the Emberwright':name==='Skyreach'?'Sella Cloudwalker':'Ilyr the Gloamkeeper',-11,-7,'The realm has changed since the Sundering. The guardian keeps an Anchor Shard. Prepare before you challenge it.',[{name:'A Realm Remembered',description:'Explore nearby ruins and return with a realm relic.'}]);
 if(name==='Verdantia')renderSettlementBuildings();
 const bossDef={name:d.guardian,color:name==='Cinderdeep'?0xc94b32:name==='Skyreach'?0x7f9ea9:name==='Umbral Wilds'?0x5b4e76:0x566e3b,face:d.accent,hp:150,damage:16,speed:1.25};
 boss=state.shards.includes(name)?null:addCreature(bossDef,12,-15,true,true,'boss-'+getRealmDef(name).id);
 if(name==='Skyreach')for(let i=0;i<5;i++){const x=-15+i*7,z=-15+(i%2)*12;const island=new THREE.Mesh(new THREE.DodecahedronGeometry(2.6,0),material(0x8caaa6));island.position.set(x,13+hash(i,5,state.worldSeed)*4,z);island.scale.y=.45;island.castShadow=true;worldGroup.add(island);}
 state.discovered=[...new Set([...state.discovered,name])];
 camera.position.set(player.x,player.y+1.2,player.z);renderRealm();renderHotbar();renderStats();updateObjective();saveGame(false);
}
function renderRealm(){const d=getRealmDef(state.realm);$('#realm-name').textContent=state.realm.toUpperCase();$('#world-seed').textContent='WAYFARER 0.7 · '+chunkCoord(player.x)+','+chunkCoord(player.z);document.documentElement.style.setProperty('--realm-accent','#'+d.accent.toString(16).padStart(6,'0'));updateObjective();}
function updateObjective(){const current=quests.find(q=>state.quests.includes(q.id)&&!state.completed.includes(q.id));$('#objective-title').textContent=current?current.name:'Explore the fourfold wilds';$('#objective-subtitle').textContent=current?current.desc:(state.shards.length===4?'Return to the Seed Beacon.':'Discover a ruin, tame a companion, or challenge a realm guardian.');}
function updateHeldItem(){const id=state.hotbar[state.selected]||'pick';if(id===heldItemId)return;heldItemId=id;while(heldItemGroup.children.length){const child=heldItemGroup.children[0];heldItemGroup.remove(child);if(child.geometry&&child.geometry!==cubeGeo)child.geometry.dispose();}const def=itemDef(id),type=def.type||'material';const part=(geo,color,pos,scale=null,rotation=null,rough=.78,metal=0)=>{const mesh=new THREE.Mesh(geo,material(color,rough,metal));mesh.position.set(...pos);if(scale)mesh.scale.set(...scale);if(rotation)mesh.rotation.set(...rotation);mesh.castShadow=true;heldItemGroup.add(mesh);return mesh;};const wood=0x876141,iron=0x9ba5a0,gold=0xc2a46d;
 if(type==='weapon'||type==='tool'||['pick','axe','blade'].includes(id)||id.includes('saber')||id.includes('glaive')||id.includes('maul')||id.includes('pike')){part(new THREE.BoxGeometry(.075,.48,.075),wood,[.2,-.25,-.4],[1,1,1],[0,0,-.3]);part(new THREE.BoxGeometry(.34,.085,.11),gold,[.2,-.02,-.4],[1,1,1],[0,0,-.3]);if(id==='pick'||id.includes('glaive')||id.includes('pike')){part(new THREE.BoxGeometry(.5,.13,.12),iron,[.18,.19,-.4],[1,1,1],[0,0,-.12],.45,.35);part(new THREE.ConeGeometry(.08,.34,5),iron,[.43,.19,-.4],[1,1,1],[0,0,-Math.PI/2],.45,.35);}else if(id==='axe'){part(new THREE.BoxGeometry(.38,.28,.12),iron,[.2,.08,-.4],[1,1,1],[0,0,.18],.42,.35);part(new THREE.ConeGeometry(.16,.42,5),iron,[.39,.08,-.4],[1,1,1],[0,0,-Math.PI/2],.42,.35);}else if(id.includes('maul')){part(new THREE.BoxGeometry(.35,.3,.25),iron,[.2,.12,-.4],[1,1,1],null,.4,.5);}else{part(new THREE.BoxGeometry(.105,.65,.065),iron,[.2,.37,-.4],[1,1,1],[0,0,-.3],.35,.45);part(new THREE.ConeGeometry(.06,.18,4),iron,[.2,.77,-.4],[1,1,1],[0,0,-.3],.35,.45);}}
 else if(def.placeable||type==='block'){const color=def.color||0x866446;part(new THREE.BoxGeometry(.34,.34,.34),color,[.18,-.18,-.48],[1,1,1],[.18,.35,.12]);if(id==='glass')part(new THREE.BoxGeometry(.36,.36,.055),0xa6d5d8,[.18,-.18,-.29],[1,1,1],null,.15,.08);}
 else if(type==='food'){part(new THREE.SphereGeometry(.16,8,7),id==='berry'?0x9c4f6a:id==='meat'?0x9b594d:0xb18b5b,[.19,-.18,-.43],[1,1,1],null,.88);part(new THREE.BoxGeometry(.19,.07,.19),0x5c784e,[.19,-.3,-.43]);}
 else if(type==='vehicle'){part(new THREE.BoxGeometry(.34,.13,.38),0x9eaa9c,[.18,-.18,-.48],[1,1,1],[.08,.15,0],.5,.25);}
 else{part(new THREE.OctahedronGeometry(.19),gold,[.18,-.18,-.45],[1,1,1],null,.38,.25);}
 }
function updateViewmodel(dt){heldSwing=Math.max(0,heldSwing-dt*3.8);const sway=started&&!paused?Math.sin(performance.now()*.006)*.012:0;viewModel.position.set(.42+sway,-.42+Math.abs(sway)*.45,-.78);viewModel.rotation.x=-heldSwing*.68;viewModel.rotation.y=heldSwing*.18;viewModel.rotation.z=-heldSwing*.22;}
function renderHotbar(){const bar=$('#hotbar');bar.innerHTML='';state.hotbar.forEach((id,i)=>{const def=itemDef(id);const el=document.createElement('button');el.className='hotbar-slot'+(state.selected===i?' selected':'');el.innerHTML='<small>'+(i+1)+'</small><span>'+escapeHtml(def.icon)+'</span><em>'+(state.inventory[id]||0)+'</em>';el.title=def.name;el.addEventListener('click',()=>{state.selected=i;renderHotbar()});bar.appendChild(el)});updateHeldItem();}
function renderStats(){for(const [id,val] of [['health',state.health],['hunger',state.hunger],['stamina',state.stamina],['thirst',state.thirst??100],['warmth',state.warmth??100]]){$('#'+id+'-fill').style.width=clamp(val,0,100)+'%';$('#'+id+'-value').textContent=Math.round(val)}}
function recordWorldEdit(realm,edit){if(!state.worldEdits)state.worldEdits={};if(!state.worldEdits[realm])state.worldEdits[realm]=[];const key=edit.type==='remove'?editKey(edit.x,edit.y,edit.z):null;if(key&&state.worldEdits[realm].some(e=>e.type==='remove'&&editKey(e.x,e.y,e.z)===key))return;state.worldEdits[realm].push(edit);}
function markNodeDepleted(nodeId){if(!nodeId)return;state.depletedNodes??=[];if(!state.depletedNodes.includes(nodeId))state.depletedNodes.push(nodeId);}
function applyWorldEdits(realm){const edits=state.worldEdits?.[realm]||[];for(const edit of edits){if(edit.type==='remove'){for(const b of [...blocks])if(Math.abs(b.position.x-edit.x)<.15&&Math.abs(b.position.y-edit.y)<.15&&Math.abs(b.position.z-edit.z)<.15){worldGroup.remove(b);blocks=blocks.filter(x=>x!==b);}}else if(edit.type==='place'){const key=chunkKey(chunkCoord(edit.x),chunkCoord(edit.z)),parent=loadedChunks.get(key)?.group||worldGroup;createBuildPiece(edit.drop||'stonewall',edit.x,edit.y,edit.z,edit.color,parent,key,edit.rotation||0);}}}
function saveGame(show=true){state.player={x:player.x,y:player.y,z:player.z};state.lastSaved=Date.now();localStorage.setItem(STORAGE,JSON.stringify(state));$('#last-save-label').textContent=new Date(state.lastSaved).toLocaleString();if(show)toast('Expedition saved locally.');}
function loadGame(){try{const raw=localStorage.getItem(STORAGE)||localStorage.getItem(LEGACY_STORAGE);const s=JSON.parse(raw||'null');if(!s)return false;Object.assign(state,s);Object.assign(player,s.player||{});player.x??=0;player.z??=8;player.y??=4;state.playStyle??='wayfarer';state.buildMode=false;state.buildRotation??=0;state.depletedNodes??=[];state.lootedRuins??=[];state.companionRoles??={};state.dungeonRecords??={};state.campfires??=[];state.settlement={level:1,beaconCharge:100,structures:0,population:1,buildings:[],reputation:0,farmTimer:0,...(state.settlement||{})};state.settlement.buildings??=[];state.inventory.waterskin??=0;state.inventory.stew??=0;state.inventory.campfire??=0;state.inventory.bedroll??=0;state.thirst??=100;state.warmth??=100;localStorage.setItem(STORAGE,JSON.stringify(state));return true;}catch{return false;}}
function changeQuest(id){if(!state.completed.includes(id)){state.completed.push(id);state.quests=state.quests.filter(q=>q!==id);state.xp+=40;state.skillPoints+=1;toast('Quest completed: '+(quests.find(q=>q.id===id)?.name||id)+' · +40 XP');if(state.shards.length===4&&!state.completed.includes('loom')&&!state.quests.includes('loom'))state.quests.push('loom');updateObjective();saveGame(false);}}
function checkQuestProgress(){if(state.quests.includes('first-tools')&&(state.inventory.pick||state.inventory.axe||state.inventory.blade))changeQuest('first-tools');if(state.quests.includes('first-gate')&&state.discovered.length>1)changeQuest('first-gate');if(state.quests.includes('anchor-1')&&state.shards.length>0)changeQuest('anchor-1');}
function checkCommunityQuestProgress(){for(const q of contentOf('quests')){if(!state.communityCompleted)state.communityCompleted=[];if(q.requirement?.item&&q.requirement?.count&&(state.inventory[q.requirement.item]||0)>=q.requirement.count&&!state.communityCompleted.includes(q.id)){state.communityCompleted.push(q.id);for(const [id,n] of Object.entries(q.reward?.items||{}))addItem(id,n);state.xp+=(q.reward?.xp||20);toast('Community quest completed: '+q.name);}}}
function startNew(style='wayfarer'){state.playStyle=style;state.mode=style==='architect'?'creative':'survival';state.buildMode=false;state.buildRotation=0;state.worldEdits={};hungerTimer=0;thirstTimer=0;enemyTimer=0;dayTime=0;state.finalBossDefeated=false;state.health=100;state.hunger=100;state.stamina=100;state.activeVehicle=null;state.activeDungeon={active:false,realm:'Verdantia'};state.inventory={wood:0,stone:0,fibre:0,berry:2,meat:1,ore:0,ember:0,cloudglass:0,lumen:0,wildseed:0,shard:0,cage:1,floor:0,beam:0,stairs:0,fence:0,door:0,glass:0,roof:0,stonepath:0,lantern:0};state.shards=[];state.tamed=[];state.quests=['awakening','first-tools','first-gate'];state.completed=[];state.realm='Verdantia';state.discovered=['Verdantia'];state.xp=0;state.skillPoints=0;state.level=1;state.glider=false;state.mount=null;player.x=0;player.z=8;state.worldSeed=Math.floor(Math.random()*900000)+100000;state.thirst=100;state.warmth=100;state.settlement={level:1,beaconCharge:100,structures:0,population:1,buildings:[],reputation:0,farmTimer:0};state.depletedNodes=[];state.lootedRuins=[];state.companionRoles={};state.companionHarvestTimer=0;state.dungeonRecords={};state.campfires=[];generateRealm('Verdantia');enterGame();toast('A new Wayfarer wakes beneath the Seed Beacon.');}
function enterGame(){started=true;paused=false;$('#main-menu').classList.add('hidden');$('#hud').classList.remove('hidden');$('#game-topbar').classList.remove('hidden');$('#world-vignette').style.display='block';renderer.domElement.requestPointerLock?.();renderHotbar();renderStats();updateObjective();}
function backToMenu(){saveGame(false);started=false;paused=false;document.exitPointerLock?.();$('#main-menu').classList.remove('hidden');$('#hud').classList.add('hidden');$('#game-topbar').classList.add('hidden');$('#pause-screen').classList.add('hidden');showPage('home');}
function showPage(page){$$('.menu-page').forEach(p=>p.classList.toggle('active',p.dataset.panel===page));$$('.nav-button').forEach(b=>b.classList.toggle('selected',b.dataset.page===page));}
$$('.nav-button').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));
$$('[data-goto]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.goto)));
$('#continue-button').addEventListener('click',()=>{if(!loadGame())return startNew();const keep={...player};generateRealm(state.realm);Object.assign(player,keep);camera.position.set(player.x,player.y,player.z);enterGame();toast('Welcome back, Wayfarer.');});
$('#new-world-button').addEventListener('click',startNew);
$('#pause-button').addEventListener('click',pauseGame);
$('#quick-journal').addEventListener('click',openJournal);
$('#quick-market').addEventListener('click',()=>openMarket(true));
$('#resume-button').addEventListener('click',()=>{paused=false;$('#pause-screen').classList.add('hidden');renderer.domElement.requestPointerLock?.();});
$('#save-exit-button').addEventListener('click',backToMenu);
$('#pause-journal').addEventListener('click',()=>{$('#pause-screen').classList.add('hidden');openJournal();});
$('#pause-market').addEventListener('click',()=>{ $('#pause-screen').classList.add('hidden');openMarket(true);});
function pauseGame(){if(!started)return;paused=true;document.exitPointerLock?.();$('#pause-screen').classList.remove('hidden');saveGame(false);}
document.addEventListener('pointerlockchange',()=>{pointerLocked=document.pointerLockElement===renderer.domElement;if(started&&!pointerLocked&&!paused){paused=true;$('#pause-screen').classList.remove('hidden')}});
document.addEventListener('mousemove',e=>{if(pointerLocked){const sens=Number($('#sens-setting').value)/10;lookYaw-=e.movementX*.002*sens;lookPitch=clamp(lookPitch-e.movementY*.002*sens,-1.35,1.35)}});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(e.repeat)return;if(e.code==='Escape'&&started){pauseGame();return;}if(e.code==='KeyQ'){for(const c of creatures)if(c.userData.tamed)c.userData.follow=!c.userData.follow;toast('Companion follow orders updated.');}if(e.code==='KeyP')openCompanionRoster();if(e.code==='KeyB'&&started)openSettlement();if(e.code==='KeyG'&&started)toggleBuildMode();if(e.code==='KeyZ'&&started&&state.buildMode){state.buildRotation=(state.buildRotation+1)%4;toast('Build rotation: '+(state.buildRotation*90)+'°');}if(e.code==='KeyH'&&started)openBuildPalette();if(e.code==='KeyG'&&started)toggleBuildMode();if(e.code==='KeyZ'&&started&&state.buildMode){state.buildRotation=(state.buildRotation+1)%4;toast('Build rotation: '+(state.buildRotation*90)+'°');}if(e.code==='KeyH'&&started)openBuildPalette();if(e.code==='KeyI')openInventory();if(e.code==='KeyK')openCrafting();if(e.code==='KeyJ')openJournal();if(e.code==='F2')openMarket(true);if(/^Digit[1-8]$/.test(e.code)){state.selected=Number(e.code.slice(5))-1;renderHotbar()}if(e.code==='KeyE')interact();if(e.code==='KeyF')captureCreature();if(e.code==='KeyR')toggleMountOrVehicle();if(e.code==='KeyM')openAtlas();if(e.code==='KeyC'){state.mode=state.mode==='creative'?'survival':'creative';toast('Mode: '+state.mode.toUpperCase());saveGame(false)}if(e.code==='KeyV')useSelected();});
document.addEventListener('keyup',e=>{keys[e.code]=false;});
document.addEventListener('contextmenu',e=>{if(started)e.preventDefault();});
renderer.domElement.addEventListener('mousedown',e=>{if(!started||paused)return;if(!pointerLocked){renderer.domElement.requestPointerLock?.();return;}if(e.button===0){heldSwing=.72;primaryAction();}if(e.button===2)placeSelected();});
$$('[data-close-modal]').forEach(el=>el.addEventListener('click',closeModal));
function openModal(html){$('#modal-content').innerHTML=html;$('#game-modal').classList.remove('hidden');}
function closeModal(){$('#game-modal').classList.add('hidden');}
function openInventory(){const entries=Object.entries(state.inventory).filter(([k,v])=>v>0);openModal('<span class="eyebrow">WAYFARER PACK</span><h2>Inventory & equipment</h2><p>Choose an item to assign it to the selected hotbar slot. Equip a weapon by selecting it, then attack with left click.</p><div class="inventory-grid">'+entries.map(([id,n])=>'<button class="inventory-cell" data-item="'+id+'">'+escapeHtml(itemDef(id).icon)+' <b>'+escapeHtml(itemDef(id).name)+'</b><small>× '+n+'</small></button>').join('')+'</div><div class="modal-actions"><button class="action-button secondary" id="open-craft-from-bag">CRAFTING</button><button class="action-button secondary" id="save-now">SAVE WORLD</button></div>');$$('[data-item]').forEach(b=>b.addEventListener('click',()=>{state.hotbar[state.selected]=b.dataset.item;renderHotbar();closeModal();toast(itemDef(b.dataset.item).name+' assigned to slot '+(state.selected+1));}));$('#open-craft-from-bag').onclick=openCrafting;$('#save-now').onclick=()=>saveGame();}
function costLabel(cost){return Object.entries(cost).map(([id,n])=>escapeHtml(itemDef(id).icon)+' '+n+' '+escapeHtml(itemDef(id).name)).join(' · ');}
function craftRecipe(r,quantity=1){
 const multiplier=Math.max(1,Math.min(99,Math.floor(quantity)));
 const canAfford=Object.entries(r.cost||{}).every(([id,n])=>state.mode==='creative'||(state.inventory[id]||0)>=n*multiplier);
 if(!canAfford){toast('Missing materials. Check the ingredient ledger.');return false;}
 if(state.mode!=='creative')for(const [id,n] of Object.entries(r.cost||{}))state.inventory[id]=(state.inventory[id]||0)-n*multiplier;
 for(const [id,n] of Object.entries(r.out||{}))state.inventory[id]=(state.inventory[id]||0)+n*multiplier;
 renderHotbar();renderStats();checkQuestProgress();checkCommunityQuestProgress();saveGame(false);
 toast('Crafted '+(r.label||'item')+(multiplier>1?' ×'+multiplier:''));return true;
}
function recipeCategory(r){
 const id=Object.keys(r.out||{})[0]||'',def=itemDef(id);
 if(r.mod)return 'community';
 if(def.type==='weapon')return 'weapons';
 if(def.type==='tool')return 'tools';
 if(def.type==='food'||def.type==='rest')return 'survival';
 if(def.type==='vehicle')return 'travel';
 if(def.type==='block'||def.placeable||def.buildShape)return 'building';
 return 'all';
}
function openCrafting(){
 const list=[...RECIPES,...contentOf('recipes').map(r=>({...r,mod:true}))];
 let category='all',query='',selected=list[0]?.id||null;
 const categories=[['all','All recipes'],['tools','Tools'],['weapons','Weapons'],['survival','Survival'],['building','Building'],['travel','Travel'],['community','Community']];
 const render=()=>{
  const filtered=list.map((r,index)=>({...r,_index:index,_category:recipeCategory(r)})).filter(r=>(category==='all'||r._category===category)&&((r.label+' '+(r.desc||'')).toLowerCase().includes(query.toLowerCase())));
  if(!filtered.some(r=>r.id===selected))selected=filtered[0]?.id||null;
  const active=filtered.find(r=>r.id===selected);
  const nav=categories.map(([id,label])=>'<button class="workbench-filter '+(category===id?'active':'')+'" data-category="'+id+'">'+label+'</button>').join('');
  const rows=filtered.map(r=>{
   const output=Object.entries(r.out||{})[0]||['wood',1],def=itemDef(output[0]);
   const affordable=Object.entries(r.cost||{}).every(([id,n])=>state.mode==='creative'||(state.inventory[id]||0)>=n);
   return '<button class="workbench-recipe '+(selected===r.id?'selected':'')+'" data-select-recipe="'+r._index+'"><span class="workbench-icon">'+escapeHtml(def.icon)+'</span><span class="workbench-recipe-copy"><b>'+escapeHtml(r.label)+'</b><small>'+escapeHtml(r.desc||'')+'</small></span><span class="workbench-state '+(affordable?'ready':'missing')+'">'+(affordable?'READY':'GATHER')+'</span></button>';
  }).join('');
  let detail='<div class="workbench-empty"><span>✧</span><b>Select a recipe</b><small>Choose a design from the ledger to see its ingredients.</small></div>';
  if(active){
   const outputRows=Object.entries(active.out||{}).map(([id,n])=>'<span class="workbench-output">'+escapeHtml(itemDef(id).icon)+' '+escapeHtml(itemDef(id).name)+' <b>× '+n+'</b></span>').join('');
   const ingredients=Object.entries(active.cost||{}).map(([id,n])=>{
    const owned=state.inventory[id]||0,ok=state.mode==='creative'||owned>=n;
    return '<div class="ingredient-row '+(ok?'owned':'short')+'"><span>'+escapeHtml(itemDef(id).icon)+' '+escapeHtml(itemDef(id).name)+'</span><b>'+owned+' / '+n+'</b></div>';
   }).join('');
   const affordable=Object.entries(active.cost||{}).every(([id,n])=>state.mode==='creative'||(state.inventory[id]||0)>=n);
   detail='<div class="workbench-detail"><div class="workbench-detail-art">'+escapeHtml(itemDef(Object.keys(active.out||{})[0]||'wood').icon)+'</div><span class="eyebrow">'+(active.mod?'COMMUNITY DESIGN':'WAYFARER CRAFT')+'</span><h3>'+escapeHtml(active.label)+'</h3><p>'+escapeHtml(active.desc||'A useful field-made item.')+'</p><div class="workbench-section-label">OUTPUT</div><div class="workbench-outputs">'+outputRows+'</div><div class="workbench-section-label">INGREDIENT LEDGER</div><div class="ingredient-list">'+ingredients+'</div><div class="workbench-actions"><button class="button-primary workbench-craft" data-quantity="1" '+(!affordable?'disabled':'')+'>CRAFT ONE</button><button class="button-secondary workbench-craft" data-quantity="5" '+(!Object.entries(active.cost||{}).every(([id,n])=>state.mode==='creative'||(state.inventory[id]||0)>=n*5)?'disabled':'')+'>CRAFT ×5</button></div>'+(state.mode==='creative'?'<small class="workbench-note">Creative mode · ingredients are not consumed.</small>':'<small class="workbench-note">Material counts update as you craft.</small>')+'</div>';
  }
  openModal('<div class="workbench"><header class="workbench-header"><div><span class="eyebrow">WAYFARER WORKSHOP · DESIGN LEDGER</span><h2>Make it. Make it yours.</h2><p>Turn gathered materials into tools, provisions, weapons and pieces for your next build.</p></div><div class="workbench-stock"><small>AVAILABLE MATERIALS</small><b>'+Object.entries(state.inventory).filter(([id,n])=>n>0&&itemDef(id).type==='material').length+' <span>types in pack</span></b></div></header><div class="workbench-toolbar"><nav class="workbench-filters">'+nav+'</nav><label class="workbench-search"><span>⌕</span><input id="workbench-search" placeholder="Find a design…" value="'+escapeHtml(query)+'"></label></div><div class="workbench-body"><div class="workbench-list"><div class="workbench-list-head"><b>DESIGN INDEX</b><small>'+filtered.length+' RECIPES</small></div>'+(rows||'<div class="workbench-empty"><b>No designs found</b><small>Try another search or category.</small></div>')+'</div><div class="workbench-detail-wrap">'+detail+'</div></div><footer class="workbench-footer"><span>Crafting is persistent · The materials you spend are saved with your expedition.</span><button class="text-link" id="open-build-from-workbench">OPEN BUILD MODE ↗</button></footer></div>');
  $('.workbench-filter').forEach(b=>b.onclick=()=>{category=b.dataset.category;render();});
  $('#workbench-search').oninput=e=>{const activeId=selected;query=e.target.value;selected=activeId;render();const input=$('#workbench-search');input.focus();input.setSelectionRange(query.length,query.length);};
  $('.workbench-recipe').forEach(b=>b.onclick=()=>{selected=list[Number(b.dataset.selectRecipe)].id;render();});
  $('.workbench-craft').forEach(b=>b.onclick=()=>{if(active){craftRecipe(active,Number(b.dataset.quantity));render();}});
  $('#open-build-from-workbench').onclick=()=>{closeModal();toggleBuildMode(true);};
 };
 render();
}
function openJournal(){const active=quests.filter(q=>state.quests.includes(q.id));const done=quests.filter(q=>state.completed.includes(q.id));const side=contentOf('quests');const lore=contentOf('lore');const ruinCount=(state.lootedRuins||[]).length,vaultClears=Object.values(state.dungeonRecords||{}).reduce((sum,n)=>sum+n,0),town=state.settlement||{};openModal('<span class="eyebrow">THE WAYFARER CHRONICLE</span><h2>Journal & discoveries.</h2><p>Anchor Shards: '+state.shards.length+'/4 · Ruin caches: '+ruinCount+' · Vault clears: '+vaultClears+' · Settlement: Lv '+(town.level||1)+' / '+(town.population||1)+' residents</p><p>Realms discovered: '+escapeHtml(state.discovered.join(', '))+'</p><h3>Campaign</h3><div class="quest-list">'+active.map(q=>'<div class="quest"><div><b>'+q.name+'</b><small>'+q.desc+'</small></div><span class="pill">ACTIVE</span></div>').join('')+(active.length?'':'<div class="empty-state">No active campaign objectives.</div>')+'</div><h3>Completed</h3><div class="quest-list">'+done.map(q=>'<div class="quest"><div><b>'+q.name+'</b><small>'+q.reward+'</small></div><span class="pill">DONE</span></div>').join('')+'</div><h3>Community quests</h3><div class="quest-list">'+side.map(q=>'<div class="quest"><div><b>'+escapeHtml(q.name)+'</b><small>'+escapeHtml(q.description)+'</small></div><span class="pill">MOD</span></div>').join('')+'</div><h3>Community discoveries</h3><div class="quest-list">'+lore.map(entry=>'<div class="quest"><div><b>'+escapeHtml(entry.title)+'</b><small>'+escapeHtml(entry.text)+'</small></div><span class="pill">LORE</span></div>').join('')+(lore.length?'':'<div class="empty-state">No community lore installed.</div>')+'</div>');}
function openAtlas(){openModal('<span class="eyebrow">THE FOURFOLD ATLAS</span><h2>Choose a realm.</h2><p>Travel is open in this 0.6 expedition build. Each realm has its own procedural landscape, resources, wildlife and guardian.</p><div class="realm-grid">'+Object.keys(REALMS).map(n=>'<button class="realm-tile '+REALMS[n].id+'" data-travel="'+n+'"><span>'+REALMS[n].icon+' '+n.toUpperCase()+'</span><b>'+REALMS[n].guardian+'</b><small>'+REALMS[n].desc+'</small></button>').join('')+contentOf('dimensions').map(n=>'<button class="realm-tile umbral" data-travel="'+escapeHtml(n.name)+'"><span>✧ COMMUNITY REALM</span><b>'+escapeHtml(n.name)+'</b><small>'+escapeHtml(n.description)+'</small></button>').join('')+'</div>');$$('[data-travel]').forEach(b=>b.addEventListener('click',()=>{changeRealm(b.dataset.travel);closeModal();toast('Crossed into '+b.dataset.travel+'.');}));}
function openJournalAndResume(){openJournal();}
function useSelected(){const id=state.hotbar[state.selected],def=itemDef(id);if(def.type==='food'){if(!takeItem(id,1))return;state.health=clamp(state.health+(def.heal||8),0,100);state.hunger=clamp(state.hunger+(def.hunger||10),0,100);state.thirst=clamp((state.thirst??100)+(def.thirst||0),0,100);state.warmth=clamp((state.warmth??100)+(def.warmth||0),0,100);renderStats();saveGame(false);toast('Used '+def.name+'.');}else if(def.type==='rest'){if(nearest(enemies,5)){toast('Find a safe place before resting.');return;}state.stamina=100;state.warmth=clamp((state.warmth??100)+35,0,100);state.health=clamp(state.health+12,0,100);renderStats();saveGame(false);toast('You rested at a safe camp.');}else if(def.type==='vehicle'){toggleMountOrVehicle();}else toast('Select a consumable, bedroll or vehicle item.');}
function primaryAction(){raycaster.setFromCamera(pointer,camera);const enemyHits=raycaster.intersectObjects(enemies.filter(e=>e.visible),true);const hitEnemy=enemyHits[0];if(hitEnemy&&hitEnemy.distance<5){const enemy=enemies.find(e=>e===hitEnemy.object||e.children.includes(hitEnemy.object));if(enemy){attackEnemy(enemy);return;}}const hits=raycaster.intersectObjects(blocks,true);if(!hits.length)return;const hit=hits[0],mesh=hit.object,drop=mesh.userData.drop||'stone';if(state.mode!=='creative'&&mesh.userData.hardness>1.2&&!(state.inventory.pick>0)){toast('Craft a mining tool to break this resource.');return;}let mined={x:mesh.position.x,y:mesh.position.y,z:mesh.position.z};if(mesh.isInstancedMesh&&hit.instanceId!==undefined){const matrix=new THREE.Matrix4(),pos=new THREE.Vector3(),quat=new THREE.Quaternion(),scale=new THREE.Vector3();mesh.getMatrixAt(hit.instanceId,matrix);matrix.decompose(pos,quat,scale);mined={x:Math.round(pos.x),y:Math.round(pos.y),z:Math.round(pos.z)};recordWorldEdit(state.realm,{type:'remove',...mined});matrix.makeScale(0,0,0);mesh.setMatrixAt(hit.instanceId,matrix);mesh.instanceMatrix.needsUpdate=true;}else{recordWorldEdit(state.realm,{type:'remove',x:mined.x,y:mined.y,z:mined.z});markNodeDepleted(mesh.userData.nodeId);if(drop==='campfire')state.campfires=(state.campfires||[]).filter(p=>p.realm!==state.realm||Math.hypot(p.x-mined.x,p.z-mined.z)>.2);mesh.parent?.remove(mesh);blocks=blocks.filter(b=>b!==mesh);worldObjects=worldObjects.filter(b=>b!==mesh);}if(['fibre','wood','stone','ore','ember','cloudglass','lumen','campfire'].includes(drop))addItem(drop,1);else addItem('stone',1);if(state.inventory.pick||state.inventory.axe)state.xp+=1;}
function placeSelected(){const id=state.hotbar[state.selected],def=itemDef(id);if(!isPlaceableItem(id)){toast('Open the build catalogue with H and choose a placeable piece.');return;}let target=buildPreviewTarget;if(!state.buildMode||!target){raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(blocks,true)[0];if(!hit){toast('Aim at a surface within reach to place a piece.');return;}const p=hit.point.clone().add(hit.face.normal.clone().multiplyScalar(.52));target={x:Math.round(p.x),y:Math.round(p.y),z:Math.round(p.z)};}if(state.buildMode&&!buildPreviewValid){toast('That space is occupied. Move the preview to a clear grid cell.');return;}if(state.mode!=='creative'&&!takeItem(id,1))return;const {x,y,z}=target,color=def.color||(id==='stonewall'?0x858e8b:0x805c3c),rotation=state.buildRotation||0,key=chunkKey(chunkCoord(x),chunkCoord(z)),parent=loadedChunks.get(key)?.group||worldGroup;createBuildPiece(id,x,y,z,color,parent,key,rotation);recordWorldEdit(state.realm,{type:'place',x,y,z,color,drop:id,rotation});if(id==='campfire'){state.campfires??=[];state.campfires.push({realm:state.realm,x,y,z});}saveGame(false);toast('Placed '+def.name+'.');}
function attackEnemy(enemy){if(player.attackCooldown>0)return;const id=state.hotbar[state.selected],def=itemDef(id);let damage=def.damage||9;if(state.mode==='creative')damage=999;enemy.userData.hp-=damage;player.attackCooldown=.48;toast('Hit '+enemy.userData.name+' for '+damage+'.');if(enemy.userData.hp<=0){defeatEnemy(enemy);}}
function defeatEnemy(enemy){const u=enemy.userData;const isBoss=u.boss&&!u.dungeonBoss,isVault=u.vault;enemy.parent?.remove(enemy);enemies=enemies.filter(e=>e!==enemy);if(u.finalBoss){state.finalBossDefeated=true;changeQuest('loom');state.xp+=500;state.skillPoints+=5;toast('THE PALE CARTOGRAPHER HAS FALLEN. The Heart Loom is yours to restore.');saveGame(false);return;}if(isVault&&state.activeDungeon?.active&&state.activeDungeon.realm===state.realm&&!enemies.some(e=>e.userData.vault)){const wave=state.activeDungeon.wave||1;if(wave<3){state.activeDungeon.wave=wave+1;spawnDungeonWave(wave+1);toast('Vault depth '+(wave+1)+' unlocked. A new wave approaches.');}else{state.activeDungeon={active:false,realm:state.realm};state.dungeonRecords??={};state.dungeonRecords[state.realm]=(state.dungeonRecords[state.realm]||0)+1;state.settlement.reputation=(state.settlement.reputation||0)+12;addItem('ore',8);addItem('lumen',5);addItem('cloudglass',2);state.xp+=180;toast('Forgotten Vault conquered · rare cache secured · +180 XP');}}if(isBoss){const coreRealm=Object.prototype.hasOwnProperty.call(REALMS,state.realm);if(coreRealm&&!state.shards.includes(state.realm)){state.shards.push(state.realm);addItem('shard',1);toast('ANCHOR SHARD RECOVERED · '+state.realm);if(state.shards.length===1)changeQuest('anchor-1');if(state.shards.length===4&&!state.quests.includes('loom')&&!state.completed.includes('loom')){state.quests.push('loom');toast('All four Anchor Shards are reunited. Return to the Seed Beacon.');}}else if(!coreRealm){addItem('lumen',4);toast('Community guardian defeated · bonus relic rewards.');}else toast('The realm guardian has been defeated again.');addItem('lumen',3);state.xp+=100;state.skillPoints+=2;}else{addItem(state.realm==='Cinderdeep'?'ember':'fibre',1);state.xp+=8;}if(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.skillPoints++;toast('Wayfarer level '+state.level+' · Skill point gained.');}saveGame(false);}
function nearest(list,max=4){let best=null,bestD=max;for(const o of list){if(!o?.visible)continue;const p=o.position||o;const d=Math.hypot(player.x-p.x,player.z-p.z);if(d<bestD){best=o;bestD=d;}}return best;}
function interact(){if(!started||paused)return;const near=nearest(interactables,4);if(near){const kind=near.userData?.kind;if(kind==='beacon'){if(state.quests.includes('awakening'))changeQuest('awakening');if(state.shards.length===4&&!state.finalBossDefeated){if(state.realm!=='Verdantia')changeRealm('Verdantia');if(!enemies.some(e=>e.userData.finalBoss)){const finalEnemy=addCreature({name:'The Pale Cartographer',color:0xbbb5cc,face:0xf1e6c9,hp:260,damage:22,speed:1.35},2,-4,true,true,'final-pale-cartographer');finalEnemy.userData.finalBoss=true;}toast('THE PALE CARTOGRAPHER EMERGES. Defeat the architect of the Sundering.');return;}if(state.realm==='Verdantia'){openSettlement();return;}if(state.finalBossDefeated){toast('The Heart Loom has been restored. The four paths breathe again.');return;}toast('The Seed Beacon hums with old light.');return;}if(kind==='portal'){openAtlas();return;}if(kind==='dungeon'){if(state.activeDungeon?.active){toast('This vault run is already active.');return;}state.activeDungeon={active:true,realm:state.realm,wave:1};spawnDungeonWave(1);toast('The Forgotten Vault awakens. Three depths stand between you and its reliquary.');return;}if(kind==='ruin'){state.lootedRuins??=[];const ruinId=near.userData.ruinId;if(state.lootedRuins.includes(ruinId)){toast('This ruin has already yielded its secrets.');return;}state.lootedRuins.push(ruinId);addItem('ore',2);addItem('lumen',1);state.xp+=35;saveGame(false);toast('Forgotten cache discovered · Ironstone, Lumen and +35 XP.');return;}if(kind==='tree'){addItem('wood',2);addItem('fibre',1);markNodeDepleted(near.userData.nodeId);near.parent?.remove(near);interactables=interactables.filter(x=>x!==near);trees=trees.filter(t=>t!==near);toast('Gathered heartwood and fibre.');saveGame(false);return;}if(kind==='npc'){openNpc(near.userData.npc);return;}}
const creature=nearest(creatures,4);if(creature){toast(creature.userData.name+' watches you curiously. Press F to attempt a bond.');return;}toast('Nothing nearby responds.');}
function captureCreature(){const c=nearest(creatures,5);if(!c){toast('No creature close enough to bond with.');return;}const id=c.userData.id;if(state.tamed.includes(id)){toast(c.userData.name+' is already your companion.');return;}if(state.mode!=='creative'&&!takeItem('cage',1)){toast('You need a Resonance Cage. Craft one at the field workbench.');return;}c.userData.tamed=true;state.tamed.push(id);state.inventory.fibre+=1;toast(c.userData.name+' has bonded with you. Press Q to call companions.');c.userData.follow=true;saveGame(false);}
function spawnDungeonWave(wave){const count=wave===1?3:wave===2?4:1,clears=state.dungeonRecords?.[state.realm]||0,difficulty=1+Math.min(clears,5)*.12;for(let i=0;i<count;i++){const bossWave=wave===3;const def=bossWave?{name:'Vaultheart Custodian',color:0x8e775c,face:0xffd28a,hp:Math.round(150*difficulty),damage:18+clears,speed:1.35}:{name:wave===1?'Vault Sentinel':'Crypt Stalker',color:wave===1?0x635a58:0x4b5560,face:0xe5b47d,hp:Math.round((wave===1?38:48)*difficulty),damage:(wave===1?10:13)+Math.floor(clears/2),speed:wave===1?1.8:2.1};const enemy=addCreature(def,player.x+(i-(count-1)/2)*3,player.z-7-(i%2)*2,true,bossWave,'vault-'+uid());enemy.userData.vault=true;enemy.userData.dungeonBoss=bossWave;}}
function spawnVehicleRig(def){if(vehicleRig)worldGroup.remove(vehicleRig);const g=new THREE.Group();const tint=def.color?new THREE.Color(def.color):0x91b8b0;const deck=new THREE.Mesh(new THREE.BoxGeometry(1.8,.18,2.8),material(tint,.38,.35,.18));deck.position.y=.1;deck.castShadow=true;g.add(deck);const railMat=material(0x354b46,.45,.3);for(const side of [-.82,.82]){const rail=new THREE.Mesh(new THREE.BoxGeometry(.12,.32,2.4),railMat);rail.position.set(side,.28,0);g.add(rail);}const glow=new THREE.Mesh(new THREE.TorusGeometry(.48,.045,6,20),material(getRealmDef(state.realm).accent,.25,.2,.75));glow.rotation.x=Math.PI/2;glow.position.y=.28;g.add(glow);g.position.set(player.x,player.y-.95,player.z);worldGroup.add(g);vehicleRig=g;}
function toggleMountOrVehicle(){if(state.mount){state.mount=null;player.speed=state.activeVehicle?10:5.2;toast('You dismounted.');return;}if(state.activeVehicle){state.activeVehicle=null;if(vehicleRig)worldGroup.remove(vehicleRig);vehicleRig=null;player.speed=5.2;toast('Vehicle parked.');return;}const c=nearest(creatures.filter(x=>x.userData.tamed&&x.userData.def.mount),4);if(c){state.mount=c.userData.id;player.speed=8.8;toast('Mounted '+c.userData.name+'.');return;}const vehicleId=state.hotbar[state.selected],v=itemDef(vehicleId);if(v.type==='vehicle'&&(state.inventory[vehicleId]||0)>0){state.activeVehicle=vehicleId;player.speed=v.speed||10;spawnVehicleRig(v);toast('Using '+v.name+'. Press R to park it.');return;}toast('Select a vehicle or stand near a tamed mount.');}
function openCompanionRoster(){const owned=creatures.filter(c=>c.userData.tamed);if(!owned.length){toast('Bond with a wild creature first.');return;}openModal('<span class="eyebrow">BONDED WILDLIFE</span><h2>Companion roles.</h2><p>Choose how each bonded creature helps your expedition. Guard companions attack nearby threats; foragers bring back a little fibre over time.</p><div class="quest-list">'+owned.map(c=>'<div class="quest"><div><b>'+escapeHtml(c.userData.name)+'</b><small>Bonded companion · '+(c.userData.def.mount?'Mountable':'Field companion')+'</small></div><select class="companion-role" data-role="'+escapeHtml(c.userData.id)+'"><option value="follow">Follow</option><option value="guard">Guard</option><option value="forager">Forager</option></select></div>').join('')+'</div><div class="modal-actions"><button class="action-button secondary" id="companion-done">DONE</button></div>');$('.companion-role').forEach(sel=>sel.value=state.companionRoles?.[sel.dataset.role]||'follow');$('.companion-role').forEach(sel=>sel.onchange=()=>{state.companionRoles[sel.dataset.role]=sel.value;saveGame(false);});$('#companion-done').onclick=closeModal;}
function openNpc(npc){const tasks=npc?.tasks||[];openModal('<span class="eyebrow">WAYFARER ENCOUNTER</span><h2>'+npc.name+'</h2><p>'+npc.dialogue+'</p><div class="quest-list">'+tasks.map(t=>'<div class="quest"><div><b>'+t.name+'</b><small>'+t.description+'</small></div><span class="pill">SIDE QUEST</span></div>').join('')+'</div><div class="modal-actions"><button class="action-button" id="npc-gift">OFFER 2 FIBRE</button><button class="action-button secondary" id="npc-close">FAREWELL</button></div>');$('#npc-gift').onclick=()=>{if(takeItem('fibre',2)){state.xp+=15;toast('The villager thanks you. Relationship improved.');closeModal();}else toast('You need 2 Wild Fibre.');};$('#npc-close').onclick=closeModal;}
const SETTLEMENT_BUILDINGS={hut:{name:'Wayfarer Homestead',cost:{wood:16,stone:8,fibre:6},people:1},farm:{name:'Sunberry Farm',cost:{wood:8,fibre:8,berry:3},people:1},workshop:{name:'Rootbound Workshop',cost:{wood:14,stone:12,ore:4},people:1},watchtower:{name:'Beacon Watchtower',cost:{wood:12,stone:20,cloudglass:3},people:1}};
function createSettlementBuilding(type,index){const def=getRealmDef('Verdantia'),group=new THREE.Group(),a=index*2.399,x=-7+Math.cos(a)*6.4,z=1+Math.sin(a)*6.4,timber=material(0x72513a),stone=material(def.rock),glow=material(def.accent,.32,.1,.45);if(type==='hut'||type==='workshop'){const body=new THREE.Mesh(new THREE.BoxGeometry(2.5,1.7,2.4),type==='hut'?timber:stone);body.position.y=.95;body.castShadow=true;group.add(body);const roof=new THREE.Mesh(new THREE.ConeGeometry(1.95,1.25,4),material(type==='hut'?0x4b392b:0x5a4740));roof.position.y=2.35;roof.rotation.y=Math.PI/4;roof.castShadow=true;group.add(roof);if(type==='workshop'){const chimney=new THREE.Mesh(cubeGeo,stone);chimney.position.set(.75,2.25,-.65);chimney.scale.set(.4,1.3,.4);group.add(chimney);const forge=new THREE.Mesh(new THREE.SphereGeometry(.35,8,8),glow);forge.position.set(0,.75,1.25);group.add(forge);}}else if(type==='farm'){const soil=new THREE.Mesh(new THREE.BoxGeometry(3.5,.18,3),material(0x59452f));soil.position.y=.12;group.add(soil);for(let row=0;row<3;row++)for(let col=0;col<4;col++){const stem=new THREE.Mesh(new THREE.CylinderGeometry(.07,.09,.65,5),material(0x557b42));stem.position.set(-1.15+col*.75,.48,.75-row*.7);group.add(stem);const berry=new THREE.Mesh(new THREE.SphereGeometry(.12,7,6),material(0xb85d69,.5));berry.position.set(-1.15+col*.75,.82,.75-row*.7);group.add(berry);}}else if(type==='watchtower'){for(const sx of [-.85,.85])for(const sz of [-.85,.85]){const post=new THREE.Mesh(cubeGeo,timber);post.position.set(sx,1.55,sz);post.scale.set(.2,3.1,.2);group.add(post);}const deck=new THREE.Mesh(cubeGeo,stone);deck.position.y=2.65;deck.scale.set(2.2,.3,2.2);group.add(deck);const lamp=new THREE.Mesh(new THREE.OctahedronGeometry(.38),glow);lamp.position.y=3.25;group.add(lamp);}group.position.set(x,terrainHeight(x,z),z);group.userData={kind:'settlement-building',buildingType:type};worldGroup.add(group);}
function renderSettlementBuildings(){if(state.realm!=='Verdantia')return;const builds=state.settlement?.buildings||[];builds.forEach((b,i)=>createSettlementBuilding(b.type,i));const residents=Math.max(0,Math.min((state.settlement?.population||1)-1,8));const names=['Tamsin the Grower','Orin the Mason','Pella the Scout','Rook the Smith','Nia the Keeper','Eren the Trader','Sable the Warden','Milo the Cook'];for(let i=0;i<residents;i++){const a=i*2.1;makeNpc(names[i],-7+Math.cos(a)*3,1+Math.sin(a)*3,'The settlement is growing. Help us keep the Seed Beacon safe and the farms productive.');}}
function buildSettlement(type){const def=SETTLEMENT_BUILDINGS[type];if(!def)return;if(state.mode!=='creative'&&!Object.entries(def.cost).every(([id,n])=>(state.inventory[id]||0)>=n)){toast('Your settlement stores do not yet have the required materials.');return;}if(state.mode!=='creative')for(const [id,n] of Object.entries(def.cost))takeItem(id,n);const index=state.settlement.buildings.length;state.settlement.buildings.push({type,createdAt:Date.now()});state.settlement.structures=state.settlement.buildings.length;state.settlement.population=(state.settlement.population||1)+def.people;state.settlement.reputation=(state.settlement.reputation||0)+5;createSettlementBuilding(type,index);makeNpc('Settler '+state.settlement.population,-7+Math.cos(index*2.1)*3,1+Math.sin(index*2.1)*3,'I made a home here because the Beacon gives us hope.');saveGame(false);toast(def.name+' completed. Settlement population: '+state.settlement.population+'.');openSettlement();}
function upgradeSettlement(){const level=state.settlement.level||1;if(level>=5){toast('Your settlement has reached its current maximum level.');return;}const costs=[{wood:20,stone:12,fibre:8},{wood:40,stone:30,ore:8},{wood:60,stone:45,lumen:12},{wood:80,stone:60,lumen:25}][level-1];if(state.mode!=='creative'&&!Object.entries(costs).every(([id,n])=>(state.inventory[id]||0)>=n)){toast('Gather the materials shown before upgrading the Beacon.');return;}if(state.mode!=='creative')for(const [id,n] of Object.entries(costs))takeItem(id,n);state.settlement.level=level+1;state.settlement.reputation=(state.settlement.reputation||0)+25;state.settlement.population=(state.settlement.population||1)+1;saveGame(false);toast('Settlement upgraded to level '+state.settlement.level+'.');openSettlement();}
function openSettlement(){if(state.realm!=='Verdantia'){toast('The Seed Beacon ledger is only available in Verdantia.');return;}const settlement=state.settlement||(state.settlement={level:1,buildings:[],population:1});settlement.buildings??=[];const level=settlement.level||1,farms=settlement.buildings.filter(b=>b.type==='farm').length,buildingCards=Object.entries(SETTLEMENT_BUILDINGS).map(([id,b])=>'<div class="recipe"><div><b>'+escapeHtml(b.name)+'</b><small>'+costLabel(b.cost)+' · +'+b.people+' resident</small></div><button class="action-button settlement-build" data-build="'+id+'">BUILD</button></div>').join(''),costs=[{wood:20,stone:12,fibre:8},{wood:40,stone:30,ore:8},{wood:60,stone:45,lumen:12},{wood:80,stone:60,lumen:25}],next=level>=5?'MAX LEVEL':costLabel(costs[level-1]);openModal('<span class="eyebrow">THE SEED BEACON · VERDANTIA</span><h2>Settlement ledger.</h2><p>Grow a refuge into a living outpost. Residents appear as you build; farms produce Sunberries while you adventure in any realm.</p><div class="quest-list"><div class="quest"><div><b>Settlement level '+level+'/5</b><small>'+settlement.structures+' structures · '+(settlement.population||1)+' residents · '+(settlement.reputation||0)+' reputation</small></div><span class="pill">LEVEL '+level+'</span></div><div class="quest"><div><b>Farm output</b><small>'+farms+' farm plots · '+(farms?'harvest every 90 seconds':'Build a farm to begin producing food')+'</small></div><span class="pill">PRODUCTION</span></div></div><h3>Construct buildings</h3><div class="recipe-list">'+buildingCards+'</div><div class="modal-actions"><button class="action-button" id="settlement-upgrade" '+(level>=5?'disabled':'')+'>UPGRADE BEACON · '+escapeHtml(next)+'</button><button class="action-button secondary" id="settlement-close">CLOSE</button></div>');$('.settlement-build').forEach(b=>b.onclick=()=>buildSettlement(b.dataset.build));$('#settlement-upgrade').onclick=upgradeSettlement;$('#settlement-close').onclick=closeModal;}
function makeNpc(name,x,z,dialogue,tasks=[]){const g=new THREE.Group();const body=new THREE.Mesh(new THREE.CylinderGeometry(.3,.4,1.3,8),material(0x60795c));body.position.y=.75;g.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.33,8,8),material(0xc69a73));head.position.y=1.65;g.add(head);g.position.set(x,terrainHeight(x,z),z);g.userData={kind:'npc',npc:{name,dialogue,tasks}};worldGroup.add(g);interactables.push(g);}

function openMarket(inGame=false){showPage('market');if(inGame){openModal('<span class="eyebrow">COMMUNITY CONTENT EXCHANGE</span><h2>Mod Marketplace.</h2><p>Open the main menu to browse full pack details, or install from the catalogue here.</p><div id="modal-market-mini" class="market-grid"></div>');renderMarketInto('#modal-market-mini');}else renderMarketplace();}
function renderMarketplace(){renderMarketInto('#market-grid');}
let catalog=[];
async function loadCatalog(){try{const r=await fetch('./marketplace/catalog.json',{cache:'no-store'});if(!r.ok)throw new Error('catalog');catalog=await r.json();$('#market-count').textContent=catalog.length;renderMarketplace();}catch(e){$('#market-grid').innerHTML='<div class="empty-state">Marketplace catalogue could not load. Check your connection or import a local JSON pack.</div>';}}
let activeFilter='all';
function renderMarketInto(selector){const root=$(selector);if(!root)return;const search=($('#market-search')?.value||'').toLowerCase();const packs=catalog.filter(p=>(activeFilter==='all'||p.category===activeFilter)&&(!search||(p.name+' '+p.description+' '+p.tags.join(' ')).toLowerCase().includes(search)));const installed=getInstalled();root.innerHTML=packs.map(p=>{const ins=installed.some(x=>x.id===p.id);return '<article class="market-card"><div class="market-art '+p.category+'">'+escapeHtml(p.icon)+'</div><div class="market-body"><span class="market-kicker">'+p.category.toUpperCase()+' · '+p.version+'</span><h3>'+escapeHtml(p.name)+'</h3><p>'+escapeHtml(p.description)+'</p><div class="market-meta"><span>BY '+escapeHtml(p.author||'COMMUNITY')+'</span><button class="market-install '+(ins?'installed':'')+'" data-pack="'+p.id+'">'+(ins?'INSTALLED ✓':'DOWNLOAD +')+'</button></div></div></article>';}).join('')||'<div class="empty-state">No creations found. Try another search or category.</div>';root.querySelectorAll('[data-pack]').forEach(b=>b.addEventListener('click',()=>installFromCatalog(b.dataset.pack)));}
$('#market-filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;activeFilter=b.dataset.filter;$$('.filter-chip').forEach(c=>c.classList.toggle('active',c===b));renderMarketplace();});
$('#market-search').addEventListener('input',renderMarketplace);
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function installFromCatalog(id){const info=catalog.find(p=>p.id===id);if(!info)return;try{const response=await fetch(info.download,{cache:'no-store'});if(!response.ok)throw new Error('Download failed');const pack=await response.json();const valid=validatePack(pack);if(!valid.ok)throw new Error(valid.reason);const current=getInstalled().filter(p=>p.id!==pack.id);current.push({...pack,enabled:true,installedAt:Date.now()});setInstalled(current);renderMarketplace();renderLibrary();toast('Installed '+pack.name+'. Restarting realm systems…');if(pack.content?.dimensions?.length)toast('New realm available in the Atlas.');}catch(e){toast(e.message||'Could not install this pack.');}}
function containsExecutableKey(value){if(Array.isArray(value))return value.some(containsExecutableKey);if(value&&typeof value==='object')return Object.entries(value).some(([k,v])=>/^(script|code|html|srcdoc|on[a-z]+)$/i.test(k)||containsExecutableKey(v));return false;}
function validatePack(p){if(!p||typeof p!=='object'||Array.isArray(p))return{ok:false,reason:'Pack must be a JSON object.'};if(!/^[a-z0-9][a-z0-9_-]{2,48}$/.test(p.id||''))return{ok:false,reason:'Invalid pack ID.'};if(typeof p.name!=='string'||p.name.length>72)return{ok:false,reason:'Pack name is missing or too long.'};if(typeof p.version!=='string'||p.version.length>24)return{ok:false,reason:'Pack version is invalid.'};if(typeof p.icon!=='string'||p.icon.length>8)return{ok:false,reason:'Pack icon is invalid.'};if(containsExecutableKey(p.content))return{ok:false,reason:'Executable content is not permitted.'};if(!p.content||typeof p.content!=='object'||Array.isArray(p.content))return{ok:false,reason:'Pack has no content manifest.'};const keys=['items','creatures','dimensions','weapons','vehicles','quests','recipes','lore'];for(const k of keys){if(p.content[k]!==undefined&&(!Array.isArray(p.content[k])||p.content[k].length>80))return{ok:false,reason:'Invalid '+k+' collection.'};}for(const k of ['items','creatures','dimensions','weapons','vehicles','quests'])for(const x of p.content[k]||[])if(!x.id||!/^[a-z0-9][a-z0-9_-]{1,48}$/.test(x.id))return{ok:false,reason:'Invalid content ID in '+k+'.'};for(const key of ['items','creatures','dimensions','weapons','vehicles','quests','recipes','lore'])for(const item of p.content[key]||[]){for(const field of ['name','label','description','desc','title','text','icon','author'])if(item[field]!==undefined&&(typeof item[field]!=='string'||item[field].length>500))return{ok:false,reason:'Invalid '+field+' field.'};if(item.icon&&item.icon.length>8)return{ok:false,reason:'Content icon is too long.'};}return{ok:true};}
function renderLibrary(){const list=$('#library-list');const packs=getInstalled();$('#installed-count').textContent=packs.length;if(!packs.length){list.innerHTML='<div class="empty-state">No community packs installed yet. Visit the Marketplace to expand your expedition.</div>';return;}list.innerHTML=packs.map(p=>'<div class="library-item"><div class="library-icon">'+escapeHtml(p.icon||'◇')+'</div><div class="library-info"><b>'+escapeHtml(p.name)+'</b><small>'+escapeHtml(p.author||'Community creator')+' · '+(p.enabled?'Enabled':'Disabled')+' · v'+escapeHtml(p.version||'1.0.0')+'</small></div><div class="library-actions"><button data-toggle="'+p.id+'">'+(p.enabled?'DISABLE':'ENABLE')+'</button><button data-remove="'+p.id+'">REMOVE</button></div></div>').join('');list.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const ps=getInstalled().map(p=>p.id===b.dataset.toggle?{...p,enabled:!p.enabled}:p);setInstalled(ps);renderLibrary();renderMarketplace();toast('Mod load state updated.');});list.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{setInstalled(getInstalled().filter(p=>p.id!==b.dataset.remove));renderLibrary();renderMarketplace();toast('Pack removed from this browser.');});}

function importPackObject(pack){const v=validatePack(pack);if(!v.ok){toast(v.reason);return;}const installed=getInstalled().filter(p=>p.id!==pack.id);installed.push({...pack,enabled:true,installedAt:Date.now()});setInstalled(installed);renderLibrary();renderMarketplace();toast('Imported '+pack.name+'.');}
$('#import-mod-button').addEventListener('click',()=>$('#pack-file-input').click());
$('#pack-file-input').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{importPackObject(JSON.parse(await file.text()));}catch{toast('That file is not a valid mod manifest.');}e.target.value='';});
function updateModCounts(){const p=getInstalled();$('#installed-count').textContent=p.length;const menuCount=$('#menu-mod-count');if(menuCount)menuCount.textContent=p.length;}
function openMarketplaceDetail(pack){openModal('<span class="eyebrow">COMMUNITY CREATION · '+pack.category.toUpperCase()+'</span><h2>'+escapeHtml(pack.name)+'</h2><p>'+escapeHtml(pack.description)+'</p><p>Creator: '+escapeHtml(pack.author||'Community')+' · Version '+escapeHtml(pack.version||'1.0.0')+'</p><div class="pill">SAFE DATA MANIFEST · NO EXECUTABLE SCRIPTS</div><div class="modal-actions"><button class="action-button" id="detail-install">DOWNLOAD & INSTALL</button><button class="action-button secondary" id="detail-close">CLOSE</button></div>');$('#detail-install').onclick=()=>{closeModal();installFromCatalog(pack.id);};$('#detail-close').onclick=closeModal;}
function openImportUrl(){openModal('<span class="eyebrow">COMMUNITY CREATION</span><h2>Import a pack URL.</h2><p>Use a direct HTTPS link to a JSON manifest, such as a raw GitHub file. Only data packs are accepted; scripts are rejected.</p><input id="pack-url" class="modal-input" placeholder="https://raw.githubusercontent.com/creator/repo/main/pack.json"><div class="modal-actions"><button class="action-button" id="fetch-pack-url">FETCH & INSTALL</button></div>');$('#fetch-pack-url').onclick=async()=>{const url=$('#pack-url').value.trim();if(!url.startsWith('https://'))return toast('Only HTTPS URLs are accepted.');try{const r=await fetch(url);if(!r.ok)throw 0;importPackObject(await r.json());closeModal();}catch{toast('Could not download a valid manifest.');}};}
function openMarketplaceSubmit(){window.open('https://github.com/osejinduc-cyber/fourfold-wildbound/issues/new?title=Community%20mod%20submission&body=Please%20include%20a%20link%20to%20your%20JSON%20manifest%20and%20a%20short%20description.','_blank','noopener');}
const oldImport=$('#import-mod-button');oldImport.addEventListener('contextmenu',e=>{e.preventDefault();openImportUrl();});
$('#import-url-button').addEventListener('click',openImportUrl);
function renderStatsAndHud(){renderStats();renderHotbar();}
function nearestSurface(){return terrainHeight(Math.round(player.x),Math.round(player.z))+1.65;}
function updateBossHud(){const b=nearest(enemies.filter(e=>e.userData.boss),22);const panel=$('#boss-health');if(!b){panel.classList.add('hidden');return;}panel.classList.remove('hidden');$('#boss-name').textContent=b.userData.name;$('#boss-fill').style.width=clamp(b.userData.hp/b.userData.maxHp*100,0,100)+'%';}
function updateInteractions(){raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects([...blocks,...enemies,...creatures,...interactables.filter(x=>x.isObject3D)],true)[0];let p='';if(hit){const o=hit.object;const root=enemies.find(e=>e===o||e.children.includes(o));const cr=creatures.find(c=>c===o||c.children.includes(o));if(root)p='Attack '+root.userData.name;else if(cr)p='Press F to bond with '+cr.userData.name;else if(o.userData.block||o.userData.terrainChunk)p='Mine '+itemDef(o.userData.drop||'stone').name;}const near=nearest(interactables,3.4);if(near){const k=near.userData.kind;p=k==='beacon'?(state.realm==='Verdantia'?'E · Settlement ledger':'E · Awaken at the Seed Beacon'):k==='portal'?'E · Open the Realm Gate':k==='dungeon'?'E · Enter the Forgotten Vault':k==='npc'?'E · Speak':k==='tree'?'E · Gather Heartwood':k==='ruin'?'E · Search Forgotten Cache':p;}$('#interaction-prompt').textContent=p;$('#interaction-prompt').style.display=p?'block':'none';}
function updateEnemies(dt){for(const e of [...enemies]){const u=e.userData;if(!e.visible)continue;const dx=player.x-e.position.x,dz=player.z-e.position.z,d=Math.hypot(dx,dz);u.alertTimer=Math.max(0,(u.alertTimer||0)-dt);const allies=enemies.filter(other=>other!==e&&other.visible&&Math.hypot(other.position.x-e.position.x,other.position.z-e.position.z)<9);if(d<20){u.alertTimer=4;for(const ally of allies)if(!ally.userData.boss)ally.userData.alertTimer=4;}const engaged=d<20||u.alertTimer>0;if(engaged){u.aiState=d<2.4?'strike':'hunt';const retreat=u.hp<u.maxHp*.18&&!u.boss&&allies.length>0;if(retreat){u.aiState='retreat';const ally=allies[0],ax=ally.position.x-e.position.x,az=ally.position.z-e.position.z,ad=Math.hypot(ax,az)||1;e.position.x-=ax/ad*u.speed*.8*dt;e.position.z-=az/ad*u.speed*.8*dt;}else{e.position.x+=dx/(d||1)*u.speed*dt;e.position.z+=dz/(d||1)*u.speed*dt;}e.position.y=terrainHeight(e.position.x,e.position.z);e.lookAt(player.x,e.position.y+1,player.z);if(d<1.8){u.attack-=dt;if(u.attack<=0){u.attack=u.boss?1.2:1.65;const damage=u.damage*(state.realm==='Cinderdeep'?1.12:1);state.health=clamp(state.health-damage,0,100);toast(u.name+' strikes for '+Math.round(damage)+'.');renderStats();if(state.health<=0)respawn();}}}else{u.aiState='patrol';u.nextThink=(u.nextThink||0)-dt;if(u.nextThink<=0){u.nextThink=2.5+hash(Math.floor(e.position.x),Math.floor(e.position.z),Math.floor(performance.now()/1000))*3;u.patrolAngle=(u.patrolAngle||0)+(hash(Math.floor(e.position.x),Math.floor(e.position.z),Math.floor(performance.now()/700))*2-1)*1.4;}const tx=e.position.x+Math.cos(u.patrolAngle||0)*u.speed*.4*dt,tz=e.position.z+Math.sin(u.patrolAngle||0)*u.speed*.4*dt;e.position.x=tx;e.position.z=tz;e.position.y=terrainHeight(tx,tz)+Math.sin(performance.now()*.001+tx)*.06;}}}
function updateWildlife(dt){for(const c of creatures){const u=c.userData;if(u.tamed)continue;const d=Math.hypot(player.x-c.position.x,player.z-c.position.z);if(d<7){u.aiState='flee';const dx=c.position.x-player.x,dz=c.position.z-player.z,dist=d||1;c.position.x+=dx/dist*(u.speed||1.5)*1.35*dt;c.position.z+=dz/dist*(u.speed||1.5)*1.35*dt;}else{u.nextThink=(u.nextThink||0)-dt;if(u.nextThink<=0){u.nextThink=2+hash(Math.floor(c.position.x),Math.floor(c.position.z),Math.floor(performance.now()/2500))*4;u.patrolAngle=(u.patrolAngle||0)+(hash(Math.floor(c.position.z),Math.floor(c.position.x),Math.floor(performance.now()/1300))*2-1)*1.5;u.aiState='forage';}const tx=c.position.x+Math.cos(u.patrolAngle||0)*(u.speed||1.5)*.2*dt,tz=c.position.z+Math.sin(u.patrolAngle||0)*(u.speed||1.5)*.2*dt;c.position.x=tx;c.position.z=tz;}c.position.y=terrainHeight(c.position.x,c.position.z);}}
function updateCompanions(dt){let foragers=0;for(const c of creatures){const u=c.userData;if(!u.tamed)continue;const role=state.companionRoles?.[u.id]||'follow';if(role==='forager')foragers++;if(state.mount===u.id){c.position.set(player.x,terrainHeight(player.x,player.z),player.z);c.visible=true;continue;}if(u.follow){const dx=player.x-c.position.x,dz=player.z-c.position.z,d=Math.hypot(dx,dz);if(d>2.2){c.position.x+=dx/d*2.2*dt;c.position.z+=dz/d*2.2*dt;c.position.y=terrainHeight(c.position.x,c.position.z);}}if(role==='guard'){const threat=nearest(enemies,7);if(threat){u.guardTimer=(u.guardTimer||0)+dt;if(u.guardTimer>1.2){u.guardTimer=0;threat.userData.hp-=4;if(threat.userData.hp<=0)defeatEnemy(threat);}}}}if(foragers){state.companionHarvestTimer=(state.companionHarvestTimer||0)+dt;if(state.companionHarvestTimer>=120){state.companionHarvestTimer=0;state.inventory.fibre=(state.inventory.fibre||0)+foragers;renderHotbar();toast('Your forager companions returned with '+foragers+' Wild Fibre.');saveGame(false);}}}
function respawn(){state.health=55;player.x=0;player.z=8;player.y=terrainHeight(0,8)+2;state.inventory.meat=Math.max(0,(state.inventory.meat||0)-1);toast('You were returned to the last Seed Beacon. One ration was lost.');renderStats();}
function updateSurvival(dt){if(state.mode==='creative'){state.hunger=100;state.thirst=100;state.warmth=100;state.health=100;state.stamina=100;return;}hungerTimer+=dt;thirstTimer+=dt;if(hungerTimer>18){hungerTimer=0;state.hunger=clamp(state.hunger-.72,0,100);if(state.hunger===0)state.health=clamp(state.health-.45,0,100);else if(state.hunger>70&&state.health<100)state.health=clamp(state.health+.18,0,100);}if(thirstTimer>14){thirstTimer=0;state.thirst=clamp((state.thirst??100)-.9,0,100);if(state.thirst===0)state.health=clamp(state.health-.65,0,100);}if(keys.ShiftLeft&&state.stamina>0)state.stamina=clamp(state.stamina-24*dt,0,100);else state.stamina=clamp(state.stamina+15*dt,0,100);const coldRealm=state.realm==='Umbral Wilds';const campfireNear=(state.campfires||[]).some(p=>p.realm===state.realm&&Math.hypot(p.x-player.x,p.z-player.z)<9);if(campfireNear)state.warmth=clamp((state.warmth??100)+2.4*dt,0,100);else if(coldRealm)state.warmth=clamp((state.warmth??100)-.18*dt,0,100);else state.warmth=clamp((state.warmth??100)-.025*dt,0,100);if(state.warmth<18)state.stamina=clamp(state.stamina-.25*dt,0,100);if(state.thirst<18)state.stamina=clamp(state.stamina-.2*dt,0,100);if(state.realm==='Cinderdeep'&&state.inventory.ember<=0&&Math.sin(performance.now()*.0004)>.92)state.health=clamp(state.health-.12,0,100);if(state.realm==='Umbral Wilds'&&Math.sin(performance.now()*.00025)>.92)state.stamina=clamp(state.stamina-.1,0,100);renderStats();if(state.health<=0)respawn();}
function updateSettlement(dt){const farms=(state.settlement?.buildings||[]).filter(b=>b.type==='farm').length;if(!farms)return;state.settlement.farmTimer=(state.settlement.farmTimer||0)+dt;if(state.settlement.farmTimer>=90){state.settlement.farmTimer=0;const yieldCount=Math.min(farms,3);state.inventory.berry=(state.inventory.berry||0)+yieldCount;renderHotbar();toast('Your Verdant farms harvested '+yieldCount+' Sunberries.');saveGame(false);}}
function updateDayNight(dt){dayTime+=dt*.004;const light=.72+Math.sin(dayTime)*.2;sun.intensity=state.realm==='Cinderdeep'?1.35:1.45+light*.62;sun.position.set(Math.cos(dayTime)*40,30+Math.sin(dayTime)*35,Math.sin(dayTime)*30);}
function animate(){requestAnimationFrame(animate);const now=performance.now(),dt=Math.min((now-lastTime)/1000,.04);lastTime=now;if(started&&!paused){const f=(keys.KeyW?1:0)-(keys.KeyS?1:0),s=(keys.KeyD?1:0)-(keys.KeyA?1:0);const run=keys.ShiftLeft&&state.stamina>2,speed=(player.speed||5.2)*(run?1.5:1);const dir=new THREE.Vector3(s,0,-f).normalize().applyAxisAngle(new THREE.Vector3(0,1,0),lookYaw);player.x+=dir.x*speed*dt;player.z+=dir.z*speed*dt;player.x=clamp(player.x,-65536,65536);player.z=clamp(player.z,-65536,65536);updateChunks(player.x,player.z);const ground=terrainHeight(Math.round(player.x),Math.round(player.z))+1.65;if(keys.Space&&player.grounded){verticalVelocity=7;player.grounded=false;}verticalVelocity-=19*dt;player.y+=verticalVelocity*dt;if(player.y<=ground){player.y=ground;verticalVelocity=0;player.grounded=true;}camera.position.set(player.x,player.y,player.z);if(vehicleRig){vehicleRig.position.set(player.x,player.y-.95,player.z);vehicleRig.rotation.y=lookYaw;}camera.rotation.set(lookPitch,lookYaw,0);updateViewmodel(dt);player.attackCooldown=Math.max(0,player.attackCooldown-dt);updateEnemies(dt);updateWildlife(dt);updateCompanions(dt);updateSurvival(dt);updateSettlement(dt);updateDayNight(dt);updateInteractions();updateBossHud();updateBuildPreview();}renderer.render(scene,camera);}
function changeRealm(name){state.realm=name;state.discovered=[...new Set([...state.discovered,name])];player.x=0;player.z=8;player.y=terrainHeight(0,8)+2;generateRealm(name);state.activeDungeon={active:false,realm:name};saveGame(false);if(state.quests.includes('first-gate')&&state.discovered.length>1)changeQuest('first-gate');}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);}
addEventListener('resize',resize);
$('#quality-setting').addEventListener('change',saveSettings);$('#fov-setting').addEventListener('input',saveSettings);$('#sens-setting').addEventListener('input',saveSettings);$('#motion-setting').addEventListener('change',saveSettings);$('#hints-setting').addEventListener('change',saveSettings);
$$('[data-realm]').forEach(b=>b.addEventListener('click',()=>{changeRealm(b.dataset.realm);enterGame();}));
$('#market-grid').addEventListener('click',e=>{const card=e.target.closest('.market-card');if(card&&!e.target.closest('[data-pack]')){const btn=card.querySelector('[data-pack]');const p=catalog.find(x=>x.id===btn?.dataset.pack);if(p)openMarketplaceDetail(p);}});
loadSettings();renderLibrary();updateModCounts();loadCatalog();loadGame();if(!localStorage.getItem(STORAGE)&&localStorage.getItem(LEGACY_STORAGE))loadGame();if(!localStorage.getItem(STORAGE))generateRealm('Verdantia');else generateRealm(state.realm);renderStatsAndHud();animate();
